extern "C" __device__
void d256_cp_async_fp32_factor_half_panel(
        float* factor,
        float* panel,
        const float* source) {
    constexpr int factor_ld = 68;
    constexpr int panel_ld = 36;
    constexpr int global_ld = 256;
    constexpr long long matrix_elements = 256LL * 256LL;
    const int sample = blockIdx.x;
    const int panel_half = blockIdx.y;
    const long long sample_base = sample * matrix_elements;
    const long long factor_index = sample_base + 2 * 64 * 256 + 2 * 64;
    const long long panel_index =
        sample_base + 2 * 64 * 256 + 3 * 64 + panel_half * 32;
    const int factor_row = threadIdx.x >> 4;
    const int factor_col = (threadIdx.x & 15) * 4;
    const unsigned factor_base = static_cast<unsigned>(
        __cvta_generic_to_shared(factor));
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        const int current_row = factor_row + load * 8;
        const unsigned factor_offset = static_cast<unsigned>(
            (current_row * factor_ld + factor_col) * sizeof(float));
        const unsigned factor_shared = factor_base + factor_offset;
        const float* factor_global =
            source + factor_index + current_row * global_ld + factor_col;
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
            :: "r"(factor_shared), "l"(factor_global));
    }
    const int panel_row = threadIdx.x >> 3;
    const int panel_col = (threadIdx.x & 7) * 4;
    const unsigned panel_base = static_cast<unsigned>(
        __cvta_generic_to_shared(panel));
    #pragma unroll
    for (int load = 0; load < 4; ++load) {
        const int current_row = panel_row + load * 16;
        const unsigned panel_offset = static_cast<unsigned>(
            (current_row * panel_ld + panel_col) * sizeof(float));
        const unsigned panel_shared = panel_base + panel_offset;
        const float* panel_global =
            source + panel_index + current_row * global_ld + panel_col;
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
            :: "r"(panel_shared), "l"(panel_global));
    }
    asm volatile("cp.async.commit_group;\n" ::);
}

