    const int sample = blockIdx.x;
    const int task = blockIdx.y;
    const int panel_tile = 1 + (task >> 1);
    const int panel_half = task & 1;
    const long long sample_base = sample * matrix_elements;
    const long long panel_output_index =
        sample_base + panel_tile * 64 + panel_half * 32;
    const long long sidecar_index =
        (sample * 5LL + panel_tile - 1) * sidecar_tile_elements
        + panel_half * 32;

    const int row = threadIdx.x >> 3;
    const int col = (threadIdx.x & 7) * 4;
    #pragma unroll
    for (int load = 0; load < 4; ++load) {
        const int current_row = row + load * 16;
        const float4 panel_values = *reinterpret_cast<const float4*>(
            panel + current_row * panel_ld + col);
        *reinterpret_cast<float4*>(
            output + panel_output_index + current_row * output_ld + col) =
            panel_values;
        __half2* packed = reinterpret_cast<__half2*>(
            sidecar + sidecar_index + current_row * sidecar_ld + col);
        packed[0] = __floats2half2_rn(panel_values.x, panel_values.y);
