            if (current_row > factor_col + 3) continue;
            const float4 factor_values = *reinterpret_cast<const float4*>(
                factor + current_row * factor_ld + factor_col);
            float* destination =
                output + sample_base + current_row * output_ld + factor_col;
            if (current_row <= factor_col) {
                *reinterpret_cast<float4*>(destination) = factor_values;
            } else {
                if (current_row <= factor_col + 1) {
                    destination[1] = factor_values.y;
